function throwToolbarModel(owner = {}) {
  const capabilities = Object.fromEntries(SLOTS.map(slot => [slot.id, { enabled: false, reason: `${slot.label} is unavailable for the current Throw Creator context.` }])), enable = (id, dispatch = `internal:${id}`) => { capabilities[id] = { enabled: true, dispatch }; };
  for (const id of ['new', 'close', 'open', 'recovery', 'run', 'project', 'stage', 'viewer-browser', 'actions-search', 'suite-switch', 'help', 'settings', 'code-structure']) enable(id);
  capabilities.save = { enabled: false, reason: 'Throw Creator has separate reviewed plan, AIR timing, scaffold, preview-profile, and PNG write authorities. Use their body actions.' };
  if (liveThrowCapture(owner)) capabilities['text-source'] = { enabled: true, dispatch: 'internal:text-source', capabilityId: 'implemented.throw-air-source', resolverId: 'throw-creator.exact-air-source', routeKind: 'selected-block' };
  else capabilities['text-source'] = { enabled: false, reason: 'Select an existing P1 or P2 AIR action to open its exact native source.' };
  if (owner.descriptor?.type === 'character' && owner.descriptor.ownerDef) capabilities['connected-resources'] = { enabled: true, dispatch: 'internal:connected-resources', routeKind: 'connected-resources' };
  else capabilities['connected-resources'] = { enabled: false, reason: 'No uniquely owned character resource set is available. Plan JSON remains body-owned.' };
  const character = owner.descriptor?.type === 'character' && owner.descriptor.ownerDef;
  for (const id of ['versus', 'training', 'sprites', 'animations', 'commands', 'states', 'sounds', 'palettes']) character ? enable(id) : capabilities[id] = { enabled: false, reason: `${SLOTS.find(slot => slot.id === id)?.label || id} requires one uniquely proven AIR owner.` };
  enable('backup');
  return adapt('code.throw', capabilities, { resolverIds: ['throw-creator.exact-air-source'] });
}

