function throwControlAvailability(input = {}) {
  const actions = Array.isArray(input.actions) ? input.actions : [];
  const plan = input.plan && typeof input.plan === 'object' ? input.plan : {};
  const errors = (Array.isArray(input.issues) ? input.issues : []).filter(issue => String(issue?.level || '').toLowerCase() === 'error');
  const navigation = (role, delta) => {
    const key = role === 'p2' ? 'p2Action' : 'p1Action';
    const index = actions.findIndex(item => Number(item?.action) === Number(plan[key]));
    if (!actions.length || index < 0) return { enabled: false, reason: `Choose an available ${role.toUpperCase()} AIR action first.` };
    if (delta < 0 && index === 0) return { enabled: false, reason: `${role.toUpperCase()} is already at the first available AIR action.` };
    if (delta > 0 && index === actions.length - 1) return { enabled: false, reason: `${role.toUpperCase()} is already at the last available AIR action.` };
    return { enabled: true, reason: '' };
  };
  const output = errors.length
    ? { enabled: false, reason: `Resolve ${errors.length} validation error${errors.length === 1 ? '' : 's'} before generating throw code or launching a live preview.` }
    : { enabled: true, reason: '' };
  const selectedActions = ['p1Action', 'p2Action'].every(key => actions.some(item => Number(item?.action) === Number(plan[key])));
  const timing = errors.length
    ? { enabled: false, reason: `Resolve ${errors.length} validation error${errors.length === 1 ? '' : 's'} before applying AIR timing.` }
    : !selectedActions
      ? { enabled: false, reason: 'Choose available P1 and P2 AIR actions before applying timing.' }
      : plan.timingMode === 'independent'
        ? { enabled: false, reason: 'Choose Match P1 ticks or Match P1 boundaries to create an AIR timing proposal.' }
        : { enabled: true, reason: '' };
  const actionSelection = actions.length
    ? { enabled: true, reason: '' }
    : { enabled: false, reason: 'This AIR file has no available actions. Add an AIR action, then reopen or refresh Throw Creator.' };
  return Object.freeze({
    loadPlan: String(input.savedPlan || '').trim() ? { enabled: true, reason: '' } : { enabled: false, reason: 'Choose a saved throw plan first.' },
    p1Previous: navigation('p1', -1), p1Next: navigation('p1', 1),
    p2Previous: navigation('p2', -1), p2Next: navigation('p2', 1),
    eventNavigation: Array.isArray(plan.events) && plan.events.length ? { enabled: true, reason: '' } : { enabled: false, reason: 'Add an interaction event before navigating between events.' },
    actionSelection,
    timing,
    disablePreview: input.previewArmed ? { enabled: true, reason: '' } : { enabled: false, reason: 'Launch Live Authoring Preview before disabling its temporary profile.' },
    output
  });
}

